    c.setListed(s.listed());
    c.setProofs(s.proofs());
    c.setSplitFrom(s.splitFrom());
    c.setLateEntry(s.lateEntry());
    c.setReminded(s.reminded());
    if (s.stated()) {
        c.bind(s.statedDue());
    }
    return c;

